1	import { A11yModule } from '@angular/cdk/a11y';
2	import { CdkConnectedOverlay, CdkOverlayOrigin, ConnectedPosition } from '@angular/cdk/overlay';
3	import {
4	  ChangeDetectionStrategy,
5	  Component,
6	  ElementRef,
7	  Injector,
8	  afterNextRender,
9	  computed,
10	  inject,
11	  input,
12	  output,
13	  signal,
14	  viewChild,
15	} from '@angular/core';
16	import { MatCalendar, MatCalendarCellClassFunction, DateFilterFn } from '@angular/material/datepicker';
17	import { format, isMonday, isWithinInterval, parseISO } from 'date-fns';
18	import { WeekRange } from '../../../core/models';
19	import { formatSelectableWeeks, formatWeekRange } from '../week';
20	import { Icon } from './icon';
21	
22	const ISO_DATE_FORMAT = 'yyyy-MM-dd';
23	const SELECTED_WEEK_CLASS = 'week-picker-selected-week';
24	
25	let nextDialogId = 0;
26	
27	@Component({
28	  selector: 'app-week-picker',
29	  changeDetection: ChangeDetectionStrategy.OnPush,
30	  imports: [A11yModule, CdkConnectedOverlay, CdkOverlayOrigin, Icon, MatCalendar],
31	  template: `
32	    <button
33	      #trigger
34	      type="button"
35	      class="trigger"
36	      cdkOverlayOrigin
37	      #triggerOrigin="cdkOverlayOrigin"
38	      aria-haspopup="dialog"
39	      [attr.aria-expanded]="isOpen()"
40	      [attr.aria-controls]="isOpen() ? dialogId : null"
41	      [attr.aria-label]="triggerName()"
42	      [disabled]="isDisabled()"
43	      (click)="toggle()"
44	    >
45	      <span class="trigger-label">
46	        <app-icon class="calendar-icon" name="calendar" [size]="18" />
47	        <span aria-live="polite">{{ weekLabel() }}</span>
48	      </span>
49	      <app-icon class="chevron-icon" [name]="isOpen() ? 'chevron-up' : 'chevron-down'" />
50	    </button>
51	
52	    <ng-template
53	      cdkConnectedOverlay
54	      [cdkConnectedOverlayOrigin]="triggerOrigin"
55	      [cdkConnectedOverlayOpen]="isOpen()"
56	      [cdkConnectedOverlayPositions]="popoverPositions"
57	      (attach)="focusSelectedWeek()"
58	      (detach)="close()"
59	      (overlayOutsideClick)="closeOnOutsideClick($event)"
60	    >
61	      <div class="week-picker-dialog" role="dialog" aria-label="Choose week" [id]="dialogId" cdkTrapFocus>
62	        <mat-calendar
63	          [startAt]="selectedMonday()"
64	          [selected]="selectedMonday()"
65	          [minDate]="earliestMonday()"
66	          [maxDate]="latestCompleteMonday()"
67	          [dateFilter]="isSelectableMonday"
68	          [dateClass]="selectedWeekClass"
69	          (_userSelection)="choose($event.value)"
70	        />
71	        <div class="helper">
72	          <p>Weeks run Monday to Sunday.</p>
73	          <p>{{ selectableWeeksLabel() }}</p>
74	        </div>
75	      </div>
76	    </ng-template>
77	  `,
78	  styles: `
79	    :host { display: block; position: relative; }
80	    .trigger {
81	      width: var(--week-picker-trigger-width); height: 44px; padding: 0 14px; display: flex; align-items: center; justify-content: space-between; gap: 10px;
82	      border: 1px solid var(--color-control-border); background: var(--color-surface); color: var(--color-ink); cursor: pointer; font: inherit;
83	    }
84	    .trigger[aria-expanded='true'] { border-color: var(--color-ink); box-shadow: inset 0 0 0 1px var(--color-ink); }
85	    .trigger:disabled { background: var(--color-disabled-fill); border-color: var(--color-disabled-border); color: var(--color-ink-2); cursor: not-allowed; }
86	    .trigger-label { display: flex; align-items: center; gap: 10px; font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
87	    .chevron-icon { color: var(--color-ink-2); }
88	    .trigger[aria-expanded='true'] .chevron-icon { color: var(--color-ink); }
89	    .trigger:disabled .calendar-icon { color: var(--color-disabled-ink); }
90	    .trigger:disabled .chevron-icon { color: var(--color-disabled-chevron); }
91	  `,
92	})
93	export class WeekPicker {
94	  readonly week = input.required<WeekRange>();
95	  readonly earliestWeek = input.required<string>();
96	  readonly latestCompleteWeek = input.required<string>();
97	
98	  readonly weekSelected = output<string>();
99	
100	  private readonly injector = inject(Injector);
101	  private readonly trigger = viewChild.required<ElementRef<HTMLButtonElement>>('trigger');
102	  private readonly calendar = viewChild(MatCalendar);
103	
104	  protected readonly dialogId = `week-picker-dialog-${nextDialogId++}`;
105	  protected readonly popoverPositions: ConnectedPosition[] = [
106	    { originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top', offsetY: 8 },
107	    { originX: 'start', originY: 'top', overlayX: 'start', overlayY: 'bottom', offsetY: -8 },
108	  ];
109	
110	  protected readonly isOpen = signal(false);
111	  protected readonly isDisabled = computed(() => this.earliestWeek() === this.latestCompleteWeek());
112	  protected readonly weekLabel = computed(() => formatWeekRange(this.week().start, this.week().end));
113	  protected readonly triggerName = computed(() => `${this.weekLabel()}, choose week`);
114	  protected readonly selectableWeeksLabel = computed(() => formatSelectableWeeks(this.earliestWeek(), this.latestCompleteWeek()));
115	  protected readonly selectedMonday = computed(() => parseISO(this.week().start));
116	  protected readonly selectedSunday = computed(() => parseISO(this.week().end));
117	  protected readonly earliestMonday = computed(() => parseISO(this.earliestWeek()));
118	  protected readonly latestCompleteMonday = computed(() => parseISO(this.latestCompleteWeek()));
119	
120	  protected readonly isSelectableMonday: DateFilterFn<Date> = (day) =>
121	    day !== null && isMonday(day) && isWithinInterval(day, { start: this.earliestMonday(), end: this.latestCompleteMonday() });
122	
123	  protected readonly selectedWeekClass: MatCalendarCellClassFunction<Date> = (day, view) =>
124	    view === 'month' && !isMonday(day) && isWithinInterval(day, { start: this.selectedMonday(), end: this.selectedSunday() })
125	      ? SELECTED_WEEK_CLASS
126	      : '';
127	
128	  protected toggle(): void {
129	    if (this.isOpen()) {
130	      this.close();
131	    } else {
132	      this.isOpen.set(true);
133	    }
134	  }
135	
136	  protected close(): void {
137	    if (!this.isOpen()) {
138	      return;
139	    }
140	    this.isOpen.set(false);
141	    this.trigger().nativeElement.focus();
142	  }
143	
144	  protected closeOnOutsideClick(event: MouseEvent): void {
145	    if (!(event.target instanceof Node && this.trigger().nativeElement.contains(event.target))) {
146	      this.close();
147	    }
148	  }
